use std::fs
use std::collections::HashMap

fn bump(counts: HashMap<string, int>, w: string) {
    if counts.contains_key(w) {
        let n: int = counts[w]
        counts.insert(w, n + 1)
    } else {
        counts.insert(w, 1)
    }
}

fn cmp_items(a: (string, int), b: (string, int)) -> int {
    if a.1 != b.1 {
        return b.1 - a.1
    }
    if a.0 < b.0 { return -1 }
    if a.0 > b.0 { return 1 }
    0
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut k: int = 0
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            k = line.trim().parse::<int>().unwrap_or(0)
            continue
        }
        let mut cur = ""
        for c in line.chars() {
            if c.is_ascii_alphanumeric() {
                cur = cur + c.to_ascii_lowercase().to_string()
            } else {
                if cur.len() > 0 {
                    bump(counts, cur)
                    cur = ""
                }
            }
        }
        if cur.len() > 0 {
            bump(counts, cur)
        }
    }
    let mut items: Vec<(string, int)> = []
    for key in counts.keys() {
        items.push((key, counts[key]))
    }
    items.sort_by(|a, b| {
        let r = cmp_items(a, b)
        if r < 0 { return std::cmp::Ordering::Less }
        if r > 0 { return std::cmp::Ordering::Greater }
        std::cmp::Ordering::Equal
    })
    let mut i: int = 0
    for it in items {
        if i >= k { break }
        println("${it.0} ${it.1}")
        i += 1
    }
}

